create or replace function public.append_shared_action_event(p_id uuid,p_episode_id uuid,p_property_id uuid,p_actor_id uuid,p_product text,p_action text,p_evidence text,p_phase text,p_request jsonb,p_before jsonb,p_after jsonb,p_result jsonb,p_links jsonb default '{}')
returns jsonb language plpgsql security invoker set search_path='' as $$
declare organization uuid;e public.shared_action_events;episode public.shared_action_episodes;origin text;job uuid;attempt uuid;context_id uuid;
begin
 if p_id is null or p_episode_id is null or p_actor_id is null or jsonb_typeof(p_request) is distinct from 'object' or jsonb_typeof(p_result) is distinct from 'object'
  or length(coalesce(p_request::text,''))+length(coalesce(p_before::text,''))+length(coalesce(p_after::text,''))+length(coalesce(p_result::text,''))>32768 then raise exception 'Invalid action event';end if;
 if p_product not in ('platform','siteforge','lumaleasing','propertyaudit','brandforge','tourspark','leadpulse','crm','forgestudio','reviewflow','marketvision','bi','knowledge','property','integrations','reports','pipelines','settings','team','agency')
  or p_action not in ('market.brief.requested','market.brief.recovered','market.brief.reviewed','market.brief.exported','market.source.requested','market.source.stopped','market.source.recovered','market.listing.saved','market.listing.removed','market.extraction.requested','market.extraction.stopped','market.extraction.recovered','market.extraction.rebased','market.extraction.applied','market.competitor.saved','market.competitor.archived','market.competitor.restored','market.unit.saved','market.unit.removed','market.configuration.saved','review.testimonial.approved','review.testimonial.revoked','review.insights.saved','review.batch.prepared','review.batch.approved','review.batch.stopped','review.batch.recovered','review.configuration.saved','review.connection.saved','review.connection.disconnected','review.intake.requested','review.intake.applied','review.intake.stopped','review.intake.recovered','review.intake.rebased','review.publication.prepared','review.publication.reported','review.publication.cancelled','review.publication.uncertain','review.response.draft_saved','review.response.approved','review.response.rejected','review.response.generation_requested','review.response.generation_started','review.response.generation_result_received','review.response.generation_completed','review.response.generation_stopped','review.response.generation_recovered','review.case.created','review.case.updated','review.case.resolved','review.case.dismissed','review.case.reopened','review.case.note_added','review.ticket.created','review.ticket.updated','review.ticket.reopened','review.analysis.started','review.analysis.result_received','review.analysis.requested','review.analysis.completed','review.analysis.stopped','review.analysis.recovered','studio.credentials.renewal_requested','studio.credentials.renewal_completed','studio.app_configuration.save','studio.app_configuration.disable','studio.connection.disconnected','studio.authorization.started','studio.authorization.cancelled','studio.authorization.applied','studio.configuration.saved','studio.metrics.requested','studio.metrics.reported','studio.metrics.reviewed','studio.attribution.reviewed','studio.media.requested','studio.media.stopped','studio.media.recovered','studio.media.completed','studio.asset.saved','studio.asset.reviewed','studio.asset.archived','studio.asset.restored','studio.asset.upload.requested','studio.asset.uploaded','studio.asset.replaced','studio.asset.upload.recovered','studio.sources.refreshed','studio.generation.recovered','studio.generation.requested','studio.generation.stopped','studio.publication.recovery_reviewed','studio.publications.scheduled','studio.publication.cancel','studio.publication.reschedule','studio.brief.saved','studio.package.created','studio.revision.saved','studio.revision.reviewed','crm.qualification.prepared','crm.qualification.approved','crm.qualification.recovered','crm.qualification.activated','crm.qualification.stopped','crm.qualification.completed','crm.bulk.prepared','crm.bulk.approved','crm.bulk.stopped','crm.delivery.recovery_requested','crm.delivery.recovery_checked','crm.delivery.approved','crm.delivery.requested','crm.delivery.completed','crm.delivery.cancelled','crm.delivery.reconciled','crm.mapping.saved','crm.mapping.previewed','crm.mapping.approved','crm.operation.requested','crm.operation.completed','crm.operation.stopped','lead.score.reviewed','lead.engagement.recorded','lead.engagement.corrected','lead.score.recalculated','lead.scoring.started','lead.scoring.completed','lead.scoring.cancelled','console.page.viewed','workflow.pause','workflow.resume','workflow.stop','workflow.delivery.reviewed','tour.outcome.recorded','tour.no_show.corrected','tour.rescheduled','tour.cancelled','tour.reminder.reviewed','tour.booked','tour.timezone.set','tour.schedule_delivery.reviewed','tour.calendar_change.reviewed','tour.calendar_event.bound','brand.research.requested','brand.research.completed','brand.research.cancelled','brand.source.saved','brand.asset.upload.requested','brand.asset.uploaded','brand.asset.reviewed','brand.import.previewed','brand.operation.requested','brand.operation.cancelled','brand.brief.saved','brand.section.generated','brand.section.regenerated','brand.section.edited','brand.section.approved','brand.contract.generated','brand.contract.imported','brand.export.created','brand.revision.started','brand.visuals.generated','brand.knowledge.published','calendar.disconnected','integration.authorization.completed','integration.authorization.started','integration.authorization.cancelled','integration.authorization.failed','email.disconnected','integration.invite.created','integration.invite.revoked','integration.replacement.requested','integration.account.replaced','luma.configuration.created','luma.configuration.saved') then raise exception 'Unregistered action';end if;
 if p_action='console.page.viewed' then
  if p_evidence<>'browser_observed' or p_phase<>'observed' or p_request-array['path']<>'{}' or p_before is not null or p_after is not null or p_links<>'{}' then raise exception 'Invalid observation';end if;
 elsif p_action in ('calendar.disconnected','integration.authorization.completed','integration.authorization.started','integration.authorization.cancelled','integration.authorization.failed','email.disconnected','integration.invite.created','integration.invite.revoked','integration.replacement.requested','integration.account.replaced') then
  if p_product<>'integrations' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid connection evidence';end if;
 elsif p_action like 'review.%' then
  if p_product<>'reviewflow' or p_evidence<>'server_confirmed' or p_phase not in('succeeded','failed') then raise exception 'Invalid review evidence';end if;
 elsif p_action like 'market.%' then
  if p_product<>'marketvision' or p_evidence<>'server_confirmed' or p_phase<>'succeeded' then raise exception 'Invalid market evidence';end if;
 elsif p_action like 'studio.%' then
  if p_product<>'forgestudio' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid editorial evidence';end if;
 elsif p_action like 'crm.%' then
  if p_product<>'crm' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid CRM evidence';end if;
 elsif p_action like 'lead.%' then
  if p_product<>'leadpulse' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid scoring evidence';end if;
 elsif p_action like 'brand.%' then
  if p_product<>'brandforge' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid brand evidence';end if;
 elsif p_action in ('luma.configuration.created','luma.configuration.saved') then
  if p_product<>'lumaleasing' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid configuration evidence';end if;
 else
  if p_product<>'tourspark' or p_evidence<>'server_confirmed' or p_phase not in ('succeeded','failed') then raise exception 'Invalid workflow evidence';end if;
 end if;
 select p.org_id into organization from public.properties p join public.profiles u on p.org_id=u.org_id where p.id=p_property_id and u.id=p_actor_id;
 if organization is null then return '{"state":"forbidden"}';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_property_id::text,12));
 job:=nullif(p_links->>'jobId','')::uuid;attempt:=nullif(p_links->>'attemptId','')::uuid;context_id:=nullif(p_links->>'contextId','')::uuid;
 select * into e from public.shared_action_events where id=p_id;
 if found then
  if (e.episode_id,e.property_id,e.actor_id,e.product,e.action,e.evidence,e.phase,e.request,e.before_state,e.after_state,e.result,e.shared_job_ref,e.shared_attempt_ref,e.context_snapshot_ref)
   is distinct from (p_episode_id,p_property_id,p_actor_id,p_product,p_action,p_evidence,p_phase,p_request,p_before,p_after,p_result,job,attempt,context_id) then return '{"state":"request_conflict"}';end if;
  return jsonb_build_object('state','replayed','eventId',e.id);
 end if;
 if job is not null and not exists(select 1 from public.shared_jobs where id=job and org_id=organization and property_id=p_property_id) then return '{"state":"link_conflict"}';end if;
 if attempt is not null and not exists(select 1 from public.shared_action_attempts where id=attempt and org_id=organization and property_id=p_property_id and (job is null or job_id=job)) then return '{"state":"link_conflict"}';end if;
 if context_id is not null and not exists(select 1 from public.shared_context_snapshots where id=context_id and org_id=organization and property_id=p_property_id) then return '{"state":"link_conflict"}';end if;
 origin:=case when p_action like 'market.%' then 'console' when p_action in('review.response.generation_started','review.response.generation_result_received','review.response.generation_completed') or(p_action='review.response.draft_saved' and p_result->>'origin'='model_result') then 'workflow' when p_action in('review.analysis.started','review.analysis.result_received','review.analysis.completed') then 'workflow' when p_action like 'review.%' then 'console' when p_action in('studio.media.completed','studio.credentials.renewal_completed') then 'workflow' when p_action like 'studio.%' then 'console' when p_action like 'lead.%' or p_action like 'crm.%' then 'console' when p_action in ('console.page.viewed','luma.configuration.created','luma.configuration.saved') then 'console' else 'workflow' end;
 insert into public.shared_action_episodes(id,org_id,property_id,actor_id,origin)values(p_episode_id,organization,p_property_id,p_actor_id,origin) on conflict(id) do nothing;
 select * into episode from public.shared_action_episodes where id=p_episode_id;
 if (episode.org_id,episode.property_id,episode.actor_id,episode.origin) is distinct from (organization,p_property_id,p_actor_id,origin) then return '{"state":"episode_conflict"}';end if;
 insert into public.shared_action_events(id,episode_id,org_id,property_id,actor_id,product,action,evidence,phase,request,before_state,after_state,result,shared_job_ref,shared_attempt_ref,context_snapshot_ref)
 values(p_id,p_episode_id,organization,p_property_id,p_actor_id,p_product,p_action,p_evidence,p_phase,p_request,p_before,p_after,p_result,job,attempt,context_id);
 return jsonb_build_object('state','recorded','eventId',p_id);
end; $$;
create or replace function public.append_marketvision_service_event(p_id uuid,p_job_id uuid,p_action text,p_phase text,p_request jsonb,p_before jsonb,p_after jsonb,p_result jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare job public.shared_jobs;e public.shared_action_events;principal text:=case when p_action='market.brief.completed'then 'marketvision.brief'when p_action like 'market.source.%'then 'marketvision.source'else 'marketvision.extraction'end;begin
 if p_id is null or p_job_id is null or p_phase not in('succeeded','failed') or jsonb_typeof(p_request) is distinct from 'object' or jsonb_typeof(p_result) is distinct from 'object' or length(coalesce(p_request::text,''))+length(coalesce(p_before::text,''))+length(coalesce(p_after::text,''))+length(coalesce(p_result::text,''))>32768 then raise exception 'Invalid market service outcome';end if;
 if p_action not in('market.brief.completed','market.source.started','market.source.result_received','market.source.held','market.extraction.started','market.extraction.result_received','market.extraction.previewed','market.extraction.held') then raise exception 'Unregistered market service outcome';end if;
 select * into job from public.shared_jobs where id=p_job_id and domain=principal;if not found or job.property_id is null then return '{"state":"not_found"}';end if;
 perform pg_advisory_xact_lock(hashtextextended(job.property_id::text,71));select * into e from public.shared_action_events where id=p_id;
 if found then if(e.property_id,e.org_id,e.shared_job_ref,e.service_principal,e.action,e.phase,e.request,e.before_state,e.after_state,e.result) is distinct from(job.property_id,job.org_id,job.id,principal,p_action,p_phase,p_request,p_before,p_after,p_result) then return '{"state":"request_conflict"}';end if;return jsonb_build_object('state','replayed','eventId',e.id);end if;
 insert into public.shared_action_episodes(id,org_id,property_id,actor_id,service_principal,origin)values(p_id,job.org_id,job.property_id,null,principal,'workflow');
 insert into public.shared_action_events(id,episode_id,org_id,property_id,actor_id,service_principal,product,action,evidence,phase,request,before_state,after_state,result,shared_job_ref,context_snapshot_ref)values(p_id,p_id,job.org_id,job.property_id,null,principal,'marketvision',p_action,'server_confirmed',p_phase,p_request,p_before,p_after,p_result,job.id,job.context_snapshot_id);
 return jsonb_build_object('state','recorded','eventId',p_id);
end$$;
create or replace function public.marketvision_decision_finish(p_id uuid,p_property_id uuid,p_actor_id uuid,p_kind text,p_resource_id uuid,p_input jsonb,p_before jsonb,p_after jsonb,p_result jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare event jsonb;begin
 insert into public.marketvision_decisions(id,org_id,property_id,actor_id,kind,resource_id,input,input_hash,before_state,after_state,result)values(p_id,(select org_id from public.properties where id=p_property_id),p_property_id,p_actor_id,p_kind,p_resource_id,p_input,public.crm_configuration_hash(p_input),p_before,p_after,p_result);
 event:=public.append_shared_action_event(p_id,p_id,p_property_id,p_actor_id,'marketvision','market.'||p_kind,'server_confirmed','succeeded',jsonb_build_object('inputHash',public.crm_configuration_hash(p_input),'resourceId',p_resource_id),case when p_before is not null then jsonb_build_object('version',p_before->'version','stateHash',public.crm_configuration_hash(p_before)) end,case when p_after is not null then jsonb_build_object('version',p_after->'version','stateHash',public.crm_configuration_hash(p_after)) end,p_result,case when (p_kind like 'extraction.%'or p_kind like 'source.%'or p_kind like 'brief.%') then coalesce((select jsonb_build_object('jobId',j.id,'contextId',j.context_snapshot_id)from public.shared_jobs j where j.id=(p_result->>'requestId')::uuid and j.property_id=p_property_id),'{}')else '{}'end);
 if event->>'state' not in('recorded','replayed') then raise exception 'Market decision history could not be saved';end if;return p_result||'{"state":"saved"}';
end$$;
create table public.marketvision_briefs(
 id uuid primary key references public.shared_jobs(id),property_id uuid not null references public.properties(id)on delete cascade,org_id uuid not null references public.organizations(id),actor_id uuid not null references public.profiles(id),context_id uuid not null references public.shared_context_snapshots(id),input jsonb not null,input_hash text not null,source_snapshot jsonb not null,source_hash text not null,state text not null default 'prepared'check(state in('prepared','ready')),version integer not null default 1,result jsonb,result_hash text,created_at timestamptz not null default clock_timestamp(),finished_at timestamptz
);
create index marketvision_brief_history on public.marketvision_briefs(property_id,created_at desc,id desc);
create index marketvision_brief_org on public.marketvision_briefs(org_id);
create index marketvision_brief_actor on public.marketvision_briefs(actor_id);
create index marketvision_brief_context on public.marketvision_briefs(context_id);
alter table public.marketvision_briefs enable row level security;
revoke all on public.marketvision_briefs from public,anon,authenticated;
grant all on public.marketvision_briefs to service_role;
create policy marketvision_brief_service on public.marketvision_briefs for all to service_role using(true)with check(true);
create function public.guard_marketvision_brief()returns trigger language plpgsql security invoker set search_path=''as $$begin
 if tg_op='DELETE'then if not exists(select 1 from public.properties where id=old.property_id)then return old;end if;raise exception 'Saved reports are retained';end if;
 if(new.id,new.property_id,new.org_id,new.actor_id,new.context_id,new.input,new.input_hash,new.source_snapshot,new.source_hash,new.created_at)is distinct from(old.id,old.property_id,old.org_id,old.actor_id,old.context_id,old.input,old.input_hash,old.source_snapshot,old.source_hash,old.created_at)then raise exception 'Saved report sources cannot change';end if;
 if old.state='ready'then raise exception 'Completed reports are immutable';end if;
 if new.state<>'ready'or new.result is null or new.result_hash is null or new.finished_at is null then raise exception 'Only a complete result can finish a report';end if;
 new.version:=old.version+1;return new;
end$$;
create trigger marketvision_brief_guard before update or delete on public.marketvision_briefs for each row execute function public.guard_marketvision_brief();
create function public.marketvision_brief_sources(p_property_id uuid,p_actor_id uuid,p_days integer)returns jsonb language plpgsql stable security invoker set search_path=''as $$declare snapshot jsonb;begin
 snapshot:=public.read_marketvision_analysis(p_property_id,p_actor_id,p_days);if snapshot->>'state'<>'ready'then return snapshot;end if;
 return snapshot||jsonb_build_object('subjectUnits',coalesce((select jsonb_agg(jsonb_build_object('id',u.id,'unit_type',u.unit_type,'bedrooms',u.bedrooms,'rent_min',u.rent_min,'rent_max',u.rent_max,'last_updated_at',u.last_updated_at,'source_url',u.source_url,'source',u.source,'effective_at',u.effective_at,'expires_at',u.expires_at)order by u.id)from public.property_units u join public.properties p on p.id=u.property_id and p.org_id=u.org_id where u.property_id=p_property_id and u.active and u.review_status='approved'and(u.effective_at is null or u.effective_at<=statement_timestamp())and(u.expires_at is null or u.expires_at>statement_timestamp())),'[]'));
end$$;
create function public.marketvision_brief_source_hash(p_snapshot jsonb)returns text language sql immutable security invoker set search_path=''as $$select public.crm_configuration_hash(p_snapshot-array['state','snapshotAt','windowStart']);$$;
create function public.begin_marketvision_brief(p_id uuid,p_property_id uuid,p_actor_id uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$
declare prior jsonb;r public.marketvision_briefs;snapshot jsonb;organization uuid;context uuid;begin
 prior:=public.marketvision_decision_start(p_id,p_property_id,p_actor_id,'brief.requested',p_input);if prior->>'state'not in('new','replayed')then return prior;end if;
 select * into r from public.marketvision_briefs where id=p_id;if found then return jsonb_build_object('state',r.state,'requestId',r.id,'version',r.version);end if;
 if(p_input-array['windowDays','reason'])<>'{}'or jsonb_typeof(p_input->'windowDays')is distinct from 'number'or p_input->>'windowDays'!~'^[0-9]+$'or(p_input->>'windowDays')::integer not between 1 and 366 then raise exception 'Choose a whole reporting window from 1 to 366 days';end if;
 snapshot:=public.marketvision_brief_sources(p_property_id,p_actor_id,(p_input->>'windowDays')::integer);if snapshot->>'state'<>'ready'then return snapshot;end if;
 if octet_length(snapshot::text)>20971520 then return '{"state":"snapshot_too_large"}';end if;
 select org_id into organization from public.properties where id=p_property_id;
 insert into public.shared_context_snapshots(org_id,property_id,source_domain,source_ref,context_payload,context_hash,captured_by)values(organization,p_property_id,'marketvision.brief',p_id::text,snapshot,public.marketvision_brief_source_hash(snapshot),p_actor_id::text)returning id into context;
 insert into public.shared_jobs(id,org_id,property_id,domain,subject_type,subject_id,lifecycle_status,status_reason,dedupe_key,payload,context_snapshot_id,max_attempts,stage,progress,current_step)values(p_id,organization,p_property_id,'marketvision.brief','market_report',p_id::text,'queued','saved_report_sources',p_id::text,jsonb_build_object('requestId',p_id),context,1,'queued',0,'Exact pricing evidence saved for local report calculation');
 insert into public.marketvision_briefs(id,property_id,org_id,actor_id,context_id,input,input_hash,source_snapshot,source_hash)values(p_id,p_property_id,organization,p_actor_id,context,p_input,public.crm_configuration_hash(p_input),snapshot,public.marketvision_brief_source_hash(snapshot));
 perform public.marketvision_decision_finish(p_id,p_property_id,p_actor_id,'brief.requested',p_id,p_input,null,jsonb_build_object('version',1,'state','prepared'),jsonb_build_object('requestId',p_id,'version',1,'sourceHash',public.marketvision_brief_source_hash(snapshot),'externalExecutionStarted',false));
 return jsonb_build_object('state','prepared','requestId',p_id,'version',1);
end$$;
create function public.complete_marketvision_brief(p_id uuid,p_property_id uuid,p_actor_id uuid,p_source_hash text,p_result jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$
declare r public.marketvision_briefs;event jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended(p_property_id::text,71));
 select * into r from public.marketvision_briefs where id=p_id and property_id=p_property_id for update;if not found then return '{"state":"not_found"}';end if;
 if not exists(select 1 from public.properties p join public.profiles a on a.org_id=p.org_id join public.profiles requester on requester.org_id=p.org_id where p.id=p_property_id and p.org_id=r.org_id and a.id=p_actor_id and requester.id=r.actor_id)then return '{"state":"forbidden"}';end if;
 if r.source_hash is distinct from p_source_hash then return '{"state":"request_conflict"}';end if;
 if r.state='ready'then if r.result_hash is distinct from public.crm_configuration_hash(p_result)then return '{"state":"request_conflict"}';end if;return jsonb_build_object('state','ready','requestId',r.id,'version',r.version);end if;
 if jsonb_typeof(p_result)is distinct from 'object'or octet_length(p_result::text)>20971520 or p_result->>'schemaVersion'is distinct from 'market-brief-v2'or p_result->>'reportId'is distinct from r.id::text or p_result->>'propertyId'is distinct from r.property_id::text or p_result->>'sourceHash'is distinct from r.source_hash or p_result->>'snapshotAt'is distinct from r.source_snapshot->>'snapshotAt'or jsonb_typeof(p_result->'analysis')is distinct from 'object'or jsonb_typeof(p_result->'recommendations')is distinct from 'array'then raise exception 'Complete this report from its exact saved source snapshot';end if;
 update public.marketvision_briefs set state='ready',result=p_result,result_hash=public.crm_configuration_hash(p_result),finished_at=clock_timestamp()where id=r.id;
 update public.shared_jobs set lifecycle_status='succeeded',status_reason='saved_report_complete',stage='completed',progress=100,finished_at=clock_timestamp(),updated_at=clock_timestamp(),current_step='Exact saved pricing brief is ready for review'where id=r.id;
 event:=public.append_marketvision_service_event(md5('brief-complete:'||r.id::text)::uuid,r.id,'market.brief.completed','succeeded',jsonb_build_object('requestId',r.id,'sourceHash',r.source_hash),'{"state":"prepared"}','{"state":"ready"}',jsonb_build_object('requestId',r.id,'resultHash',public.crm_configuration_hash(p_result),'requestedBy',r.actor_id,'externalExecutionStarted',false));
 if event->>'state'not in('recorded','replayed')then raise exception 'Report outcome could not be recorded';end if;
 return jsonb_build_object('state','ready','requestId',r.id,'version',r.version+1);
end$$;
create function public.read_marketvision_briefs(p_property_id uuid,p_actor_id uuid,p_request_id uuid default null,p_cursor uuid default null)returns jsonb language plpgsql stable security invoker set search_path=''as $$
declare r public.marketvision_briefs;anchor public.marketvision_briefs;organization uuid;items jsonb;snapshot jsonb;begin
 select p.org_id into organization from public.properties p join public.profiles a on a.org_id=p.org_id where p.id=p_property_id and a.id=p_actor_id;if not found then return '{"state":"forbidden"}';end if;
 if p_request_id is not null then
  select * into r from public.marketvision_briefs where id=p_request_id and property_id=p_property_id and org_id=organization;if not found then return '{"state":"not_found"}';end if;
  snapshot:=public.marketvision_brief_sources(p_property_id,p_actor_id,(r.input->>'windowDays')::integer);
  return jsonb_build_object('state','ready','report',to_jsonb(r),'sourceChanged',case when snapshot->>'state'='ready'then r.source_hash is distinct from public.marketvision_brief_source_hash(snapshot)else null end,'currentEvidenceState',snapshot->>'state','ageSeconds',extract(epoch from(statement_timestamp()-r.created_at)),
   'decisions',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'kind',d.kind,'input',d.input,'result',d.result,'createdAt',d.created_at)order by d.created_at,d.id)from public.marketvision_decisions d where d.property_id=p_property_id and d.org_id=organization and d.resource_id=r.id and d.kind in('brief.reviewed','brief.exported','brief.recovered')),'[]'));
 end if;
 if p_cursor is not null then select * into anchor from public.marketvision_briefs where id=p_cursor and property_id=p_property_id and org_id=organization;if not found then return '{"state":"cursor_changed"}';end if;end if;
 select coalesce(jsonb_agg(q.item order by q.created_at desc,q.id desc),'[]')into items from(select entry.created_at,entry.id,jsonb_build_object('id',entry.id,'state',entry.state,'version',entry.version,'createdAt',entry.created_at,'windowDays',entry.input->'windowDays','reason',entry.input->>'reason')item from public.marketvision_briefs entry where entry.property_id=p_property_id and entry.org_id=organization and(p_cursor is null or(entry.created_at,entry.id)<(anchor.created_at,anchor.id))order by entry.created_at desc,entry.id desc limit 21)q;
 return jsonb_build_object('state','ready','reports',case when jsonb_array_length(items)>20 then items-20 else items end,'nextCursor',case when jsonb_array_length(items)>20 then items->19->>'id'else null end,'legacyCount',(select count(*)from public.market_insights where property_id=p_property_id and insight_type='market_brief'));
end$$;
create function public.recover_marketvision_brief(p_id uuid,p_property_id uuid,p_actor_id uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$
declare prior jsonb;r public.marketvision_briefs;begin
 prior:=public.marketvision_decision_start(p_id,p_property_id,p_actor_id,'brief.recovered',p_input);if prior->>'state'<>'new'then return prior;end if;
 if(p_input-array['briefId','expectedVersion','reason'])<>'{}'then raise exception 'Review the saved report identity';end if;
 select * into r from public.marketvision_briefs where id=(p_input->>'briefId')::uuid and property_id=p_property_id and org_id=(select org_id from public.properties where id=p_property_id)for update;if not found then return '{"state":"not_found"}';end if;
 if r.version is distinct from(p_input->>'expectedVersion')::integer then return '{"state":"stale_report"}';end if;
 return public.marketvision_decision_finish(p_id,p_property_id,p_actor_id,'brief.recovered',r.id,p_input,jsonb_build_object('version',r.version,'state',r.state),jsonb_build_object('version',r.version,'state',r.state),jsonb_build_object('requestId',r.id,'version',r.version,'externalExecutionStarted',false));
end$$;
-- Only service code can assemble a report; every function rechecks its property/actor scope.
revoke all on function public.marketvision_brief_sources(uuid,uuid,integer),public.marketvision_brief_source_hash(jsonb),public.begin_marketvision_brief(uuid,uuid,uuid,jsonb),public.complete_marketvision_brief(uuid,uuid,uuid,text,jsonb),public.read_marketvision_briefs(uuid,uuid,uuid,uuid),public.recover_marketvision_brief(uuid,uuid,uuid,jsonb)from public,anon,authenticated;
grant execute on function public.marketvision_brief_sources(uuid,uuid,integer),public.marketvision_brief_source_hash(jsonb),public.begin_marketvision_brief(uuid,uuid,uuid,jsonb),public.complete_marketvision_brief(uuid,uuid,uuid,text,jsonb),public.read_marketvision_briefs(uuid,uuid,uuid,uuid),public.recover_marketvision_brief(uuid,uuid,uuid,jsonb)to service_role;
create function public.review_marketvision_brief(p_id uuid,p_property_id uuid,p_actor_id uuid,p_input jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$
declare prior jsonb;r public.marketvision_briefs;recommendation jsonb;last_review public.marketvision_decisions;current_source jsonb;begin
 prior:=public.marketvision_decision_start(p_id,p_property_id,p_actor_id,'brief.reviewed',p_input);if prior->>'state'<>'new'then return prior;end if;
 if(p_input-array['briefId','expectedVersion','recommendationId','decision','expectedReviewId','acknowledgedSourceChange','reason'])<>'{}'or p_input->>'decision'not in('consider','dismiss')or p_input->>'decision'is null or not(p_input?'expectedReviewId')or jsonb_typeof(p_input->'acknowledgedSourceChange')is distinct from 'boolean'then raise exception 'Choose the exact recommendation and review reason';end if;
 select * into r from public.marketvision_briefs where id=(p_input->>'briefId')::uuid and property_id=p_property_id and org_id=(select org_id from public.properties where id=p_property_id)for update;if not found then return '{"state":"not_found"}';end if;
 if r.state<>'ready'or r.version is distinct from(p_input->>'expectedVersion')::integer then return '{"state":"stale_report"}';end if;
 select value into recommendation from jsonb_array_elements(r.result->'recommendations')where value->>'id'=p_input->>'recommendationId';if recommendation is null then return '{"state":"not_found"}';end if;
 select * into last_review from public.marketvision_decisions where property_id=p_property_id and org_id=r.org_id and resource_id=r.id and kind='brief.reviewed'and input->>'recommendationId'=p_input->>'recommendationId'order by created_at desc,id desc limit 1;
 if last_review.id is distinct from(p_input->>'expectedReviewId')::uuid then return '{"state":"stale_review"}';end if;
 current_source:=public.marketvision_brief_sources(p_property_id,p_actor_id,(r.input->>'windowDays')::integer);
 if p_input->>'decision'='consider'and(current_source->>'state'<>'ready'or(r.source_hash is distinct from public.marketvision_brief_source_hash(current_source)and p_input->>'acknowledgedSourceChange'<>'true'))then return '{"state":"source_changed"}';end if;
 return public.marketvision_decision_finish(p_id,p_property_id,p_actor_id,'brief.reviewed',r.id,p_input,jsonb_build_object('reviewId',last_review.id,'decision',last_review.input->>'decision'),jsonb_build_object('reviewId',p_id,'decision',p_input->>'decision'),jsonb_build_object('requestId',r.id,'reviewId',p_id,'recommendationId',p_input->>'recommendationId','decision',p_input->>'decision','sourceHash',r.source_hash,'sourceChanged',r.source_hash is distinct from public.marketvision_brief_source_hash(current_source),'executionStarted',false,'businessOutcome','unknown'));
end$$;
create table public.marketvision_brief_exports(
 id uuid primary key references public.marketvision_decisions(id),brief_id uuid not null references public.marketvision_briefs(id),property_id uuid not null references public.properties(id)on delete cascade,org_id uuid not null references public.organizations(id),format text not null check(format in('json','markdown')),content text not null,content_hash text not null,created_at timestamptz not null default clock_timestamp()
);
create index marketvision_brief_export_brief on public.marketvision_brief_exports(brief_id);
create index marketvision_brief_export_property on public.marketvision_brief_exports(property_id);
create index marketvision_brief_export_org on public.marketvision_brief_exports(org_id);
alter table public.marketvision_brief_exports enable row level security;
revoke all on public.marketvision_brief_exports from public,anon,authenticated;
grant all on public.marketvision_brief_exports to service_role;
create policy marketvision_brief_export_service on public.marketvision_brief_exports for all to service_role using(true)with check(true);
create trigger marketvision_brief_export_guard before update or delete on public.marketvision_brief_exports for each row execute function public.guard_marketvision_decision();
create function public.export_marketvision_brief(p_id uuid,p_property_id uuid,p_actor_id uuid,p_input jsonb,p_content text)returns jsonb language plpgsql security invoker set search_path=''as $$
declare prior jsonb;r public.marketvision_briefs;e public.marketvision_brief_exports;hash text;begin
 prior:=public.marketvision_decision_start(p_id,p_property_id,p_actor_id,'brief.exported',p_input);if prior->>'state'not in('new','replayed')then return prior;end if;
 if prior->>'state'='replayed'then select * into e from public.marketvision_brief_exports where id=p_id and property_id=p_property_id;return jsonb_build_object('state','replayed','requestId',e.brief_id,'exportId',e.id,'format',e.format,'content',e.content,'contentHash',e.content_hash);end if;
 if(p_input-array['briefId','expectedVersion','format','reason'])<>'{}'or p_input->>'format'not in('json','markdown')or p_input->>'format'is null or octet_length(p_content)not between 10 and 20971520 or p_content is null then raise exception 'Review the exact saved report download';end if;
 select * into r from public.marketvision_briefs where id=(p_input->>'briefId')::uuid and property_id=p_property_id and org_id=(select org_id from public.properties where id=p_property_id)for update;if not found then return '{"state":"not_found"}';end if;
 if r.state<>'ready'or r.version is distinct from(p_input->>'expectedVersion')::integer then return '{"state":"stale_report"}';end if;
 hash:=encode(extensions.digest(convert_to(p_content,'UTF8'),'sha256'),'hex');
 perform public.marketvision_decision_finish(p_id,p_property_id,p_actor_id,'brief.exported',r.id,p_input,null,jsonb_build_object('contentHash',hash,'format',p_input->>'format'),jsonb_build_object('requestId',r.id,'exportId',p_id,'format',p_input->>'format','contentHash',hash,'reportHash',r.result_hash,'bytes',octet_length(p_content),'downloadConfirmed',false,'externalDelivery',false));
 insert into public.marketvision_brief_exports(id,brief_id,property_id,org_id,format,content,content_hash)values(p_id,r.id,p_property_id,r.org_id,p_input->>'format',p_content,hash);
 return jsonb_build_object('state','saved','requestId',r.id,'exportId',p_id,'format',p_input->>'format','content',p_content,'contentHash',hash);
end$$;
revoke all on function public.review_marketvision_brief(uuid,uuid,uuid,jsonb),public.export_marketvision_brief(uuid,uuid,uuid,jsonb,text)from public,anon,authenticated;
grant execute on function public.review_marketvision_brief(uuid,uuid,uuid,jsonb),public.export_marketvision_brief(uuid,uuid,uuid,jsonb,text)to service_role;
-- Retain historical reports while closing unrecorded browser writes.
revoke insert,update,delete on public.market_insights from public,anon,authenticated;
create function public.read_marketvision_legacy_briefs(p_property_id uuid,p_actor_id uuid,p_request_id uuid default null,p_cursor uuid default null)returns jsonb language plpgsql stable security invoker set search_path=''as $$
declare r public.market_insights;anchor public.market_insights;items jsonb;begin
 if not exists(select 1 from public.properties p join public.profiles a on a.org_id=p.org_id where p.id=p_property_id and a.id=p_actor_id)then return '{"state":"forbidden"}';end if;
 if p_request_id is not null then select * into r from public.market_insights where id=p_request_id and property_id=p_property_id and insight_type='market_brief';if not found then return '{"state":"not_found"}';end if;return jsonb_build_object('state','ready','legacyReport',jsonb_build_object('id',r.id,'generatedAt',r.generated_at,'data',r.data),'qualification','Historical report only; its original inputs and confidence claims were not qualified by the saved-source workflow.');end if;
 if p_cursor is not null then select * into anchor from public.market_insights where id=p_cursor and property_id=p_property_id and insight_type='market_brief';if not found then return '{"state":"cursor_changed"}';end if;end if;
 select coalesce(jsonb_agg(q.item order by q.recorded_at desc,q.id desc),'[]')into items from(select id,coalesce(generated_at,created_at,'epoch'::timestamptz)recorded_at,jsonb_build_object('id',id,'createdAt',coalesce(generated_at,created_at))item from public.market_insights where property_id=p_property_id and insight_type='market_brief'and(p_cursor is null or(coalesce(generated_at,created_at,'epoch'::timestamptz),id)<(coalesce(anchor.generated_at,anchor.created_at,'epoch'::timestamptz),anchor.id))order by recorded_at desc,id desc limit 21)q;
 return jsonb_build_object('state','ready','legacyReports',case when jsonb_array_length(items)>20 then items-20 else items end,'nextCursor',case when jsonb_array_length(items)>20 then items->19->>'id'else null end);
end$$;
revoke all on function public.read_marketvision_legacy_briefs(uuid,uuid,uuid,uuid)from public,anon,authenticated;
grant execute on function public.read_marketvision_legacy_briefs(uuid,uuid,uuid,uuid)to service_role;
